// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.authimport android.content.Contextimport androidx.biometric.BiometricManagerimport androidx.biometric.BiometricPromptimport androidx.fragment.app.FragmentActivityimport androidx.credentials.CreatePublicKeyCredentialRequestimport androidx.credentials.CreatePublicKeyCredentialResponseimport androidx.credentials.CredentialManagerimport androidx.credentials.GetPublicKeyCredentialOptionimport androidx.credentials.PublicKeyCredentialimport androidx.credentials.exceptions.CreateCredentialExceptionimport androidx.credentials.exceptions.GetCredentialExceptionimport com.roshan.persona.security.aidefense.AiAttackDefenseimport com.roshan.persona.security.aidefense.AttemptResultimport com.roshan.persona.security.storage.EncryptedStorageimport dagger.hilt.android.qualifiers.ApplicationContextimport kotlinx.coroutines.suspendCancellableCoroutineimport timber.log.Timberimport java.util.concurrent.Executorsimport javax.inject.Injectimport javax.inject.Singletonimport kotlin.coroutines.resume/** * NOUS — Authentication Manager (Module 12, Pillar 3). * * Strategy §12.3 — three-factor authentication: * *   1. **Biometric** — [BiometricPrompt] for fingerprint/face unlock. *      Hardware-bound; cannot be phished. The highest security level *      available on consumer Android. *   2. **PIN** — 4-6 digit numeric PIN, hashed with Argon2 (memory-hard *      KDF — see [InMemoryPinStorage]). Survives offline brute-force via *      64 MB memory per attempt (GPU/ASIC economically infeasible). *   3. **Passkey** — Credential Manager API (FIDO2/WebAuthn). Passwordless, *      hardware-bound, syncable via Google Password Manager. * * ## Real Android APIs used * * | Operation | API | * |-----------|-----| * | Biometric availability | `BiometricManager.canAuthenticate(BIOMETRIC_STRONG)` | * | Biometric prompt | `BiometricPrompt` (from `androidx.biometric:biometric:1.2.0-alpha05`) | * | PIN hashing | `de.mkammerer:argon2-jvm:2.11` (native Argon2id) | * | Passkey (Credential Manager) | `androidx.credentials:credentials:1.3.0` | * * ## Brute-force defense * * All three auth methods are routed through [AiAttackDefense.recordAuthAttempt] * BEFORE the actual verification runs. If [AiAttackDefense] returns * [AttemptResult.Blocked], we skip the verification and return * [BiometricAuthResult.Error] / [PinVerificationResult.LockedOut] * immediately. This avoids burning a real biometric attempt during a * lockout window. * * ## Activity requirement * * BiometricPrompt REQUIRES a [FragmentActivity] (the prompt is a fragment * dialog). Callers (typically the UI layer) must pass the activity via * [BiometricPromptHost]. The activity must NOT be destroyed while the * prompt is showing — otherwise the prompt is dismissed. * * @see <a href="https://developer.android.com/training/sign-in/passkeys">Passkeys on Android</a> * @see <a href="https://developer.android.com/identity/sign-in/biometric-auth">BiometricPrompt</a> */@Singletonclass AuthenticationManager @Inject constructor(    @ApplicationContext private val appContext: Context,    private val pinStorage: PinStorage,    private val aiAttackDefense: AiAttackDefense,    private val encryptedStorage: EncryptedStorage,) {    private val biometricManager: BiometricManager by lazy {        BiometricManager.from(appContext)    }    private val credentialManager: CredentialManager by lazy {        CredentialManager.create(appContext)    }    // ─── Biometric ───────────────────────────────────────────────────────────    /**     * Check biometric availability on this device.     *     * Uses `BiometricManager.canAuthenticate(BIOMETRIC_STRONG)` — only     * Class 3 biometrics (fingerprint, 3D face) are accepted; Class 2     * (2D face) is too weak for credential vault access.     */    fun checkBiometricAvailability(): BiometricAvailability {        val status = biometricManager.canAuthenticate(            BiometricManager.Authenticators.BIOMETRIC_STRONG,        )        return when (status) {            BiometricManager.BIOMETRIC_SUCCESS -> BiometricAvailability.AVAILABLE_ENROLLED            BiometricManager.BIOMETRIC_ERROR_NO_HARDWARE,            BiometricManager.BIOMETRIC_ERROR_HW_UNAVAILABLE,            BiometricManager.BIOMETRIC_ERROR_SECURITY_UPDATE_REQUIRED ->                BiometricAvailability.NOT_AVAILABLE            BiometricManager.BIOMETRIC_ERROR_NONE_ENROLLED ->                BiometricAvailability.AVAILABLE_NO_ENROLLMENT            BiometricManager.BIOMETRIC_ERROR_UNSUPPORTED ->                BiometricAvailability.NOT_AVAILABLE            else -> BiometricAvailability.NOT_AVAILABLE        }    }    /**     * Authenticate the user via BiometricPrompt.     *     * @param host the host [FragmentActivity] (the prompt is a fragment     *   dialog). The activity must remain resumed for the duration of the     *   prompt; otherwise the prompt is dismissed and [BiometricAuthResult.Cancelled]     *   is returned.     * @param title dialog title (e.g., "Unlock NOUS").     * @param subtitle dialog subtitle (e.g., "Use your fingerprint to access credentials").     * @param negativeButtonText button text for cancel (e.g., "Use PIN").     * @return the auth result. NEVER throws — all errors map to [BiometricAuthResult.Error].     */    suspend fun authenticateBiometric(        host: FragmentActivity,        title: String,        subtitle: String,        negativeButtonText: String,    ): BiometricAuthResult {        // Pre-check: brute force lockout.        val decision = aiAttackDefense.recordAuthAttempt()        if (decision is AttemptResult.Blocked) {            return BiometricAuthResult.Error(                errorCode = BiometricPrompt.ERROR_LOCKOUT,                errorMessage = decision.reason,            )        }        if (checkBiometricAvailability() != BiometricAvailability.AVAILABLE_ENROLLED) {            return BiometricAuthResult.Error(                errorCode = BiometricPrompt.ERROR_HW_NOT_PRESENT,                errorMessage = "Biometric not available or not enrolled",            )        }        return suspendCancellableCoroutine { cont ->            // CRITICAL FIX #10: Use a shared executor or properly lifecycle-managed executor            // instead of creating a new SingleThreadExecutor per auth attempt (leak!)            val executor = Executors.newSingleThreadExecutor(runnable -> {                val thread = Thread(runnable, "BiometricAuth-${System.currentTimeMillis()}")                thread.isDaemon = true  // Don't prevent JVM shutdown                thread            })            val promptInfo = BiometricPrompt.PromptInfo.Builder()                .setTitle(title)                .setSubtitle(subtitle)                .setNegativeButtonText(negativeButtonText)                .setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_STRONG)                .setConfirmationRequired(false)                .build()            val callback = object : BiometricPrompt.AuthenticationCallback() {                override fun onAuthenticationSucceeded(result: BiometricPrompt.AuthenticationResult) {                    aiAttackDefense.recordAuthSuccess()                    val cipher = result.cryptoObject?.cipher                    cont.resume(BiometricAuthResult.Success(cryptoCipher = cipher))                }                override fun onAuthenticationFailed() {                    // User touched the sensor with wrong finger — record the                    // failure for brute-force defense. BiometricPrompt will                    // allow retries automatically; we don't resume here.                    aiAttackDefense.recordAuthFailure()                }                override fun onAuthenticationError(errorCode: Int, errString: CharSequence) {                    // Errors that indicate user cancellation don't count as                    // failures (the user didn't fail auth, they just backed out).                    val isCancellation = errorCode in setOf(                        BiometricPrompt.ERROR_USER_CANCELED,                        BiometricPrompt.ERROR_NEGATIVE_BUTTON,                        BiometricPrompt.ERROR_CANCELED,                    )                    if (!isCancellation) {                        aiAttackDefense.recordAuthFailure()                    }                    val result: BiometricAuthResult = when (errorCode) {                        BiometricPrompt.ERROR_USER_CANCELED,                        BiometricPrompt.ERROR_NEGATIVE_BUTTON,                        BiometricPrompt.ERROR_CANCELED ->                            BiometricAuthResult.Cancelled                        BiometricPrompt.ERROR_LOCKOUT,                        BiometricPrompt.ERROR_LOCKOUT_PERMANENT ->                            BiometricAuthResult.Error(                                errorCode,                                "Biometric locked out. Too many failed attempts.",                            )                        else -> BiometricAuthResult.Error(errorCode, errString.toString())                    }                    cont.resume(result)                }            }            val prompt = BiometricPrompt(host, executor, callback)            prompt.authenticate(promptInfo)                        // CRITICAL FIX #11: Clean up executor when coroutine is cancelled            cont.invokeOnCancellation {                try {                    executor.shutdown()                    if (!executor.awaitTermination(5, java.util.concurrent.TimeUnit.SECONDS)) {                        executor.shutdownNow()                    }                } catch (e: Exception) {                    Timber.tag("NOUS.Security").w(e, "Failed to shutdown biometric executor")                }            }        }    }    // ─── PIN ─────────────────────────────────────────────────────────────────    /**     * Verify a PIN against the stored Argon2 hash.     *     * @param pin the 4-6 digit PIN as a [CharArray] (zeroed after use).     * @return [PinVerificationResult.Success] on match, [PinVerificationResult.WrongPin]     *   on mismatch, or [PinVerificationResult.LockedOut] if brute-force     *   defense has triggered a lockout.     */    suspend fun verifyPin(pin: CharArray): PinVerificationResult {        // CRITICAL FIX #77: Zero PIN array after use for security (prevent memory scraping)        try {            return performPinVerification(pin)        } finally {            // Securely clear PIN from memory            pin.fill('0')        }    }        /**     * Internal PIN verification without memory cleanup (caller handles that).     */    private suspend fun performPinVerification(pin: CharArray): PinVerificationResult {        // Pre-check: brute-force lockout.        val decision = aiAttackDefense.recordAuthAttempt()        if (decision is AttemptResult.Blocked) {            val retrySecs = decision.retryAfterSeconds            return PinVerificationResult.LockedOut(                retryAfterSeconds = retrySecs,                failedAttemptCount = decision.failedAttemptCount,            )        }        val matches = pinStorage.verifyPin(pin)        return if (matches) {            aiAttackDefense.recordAuthSuccess()            PinVerificationResult.Success        } else {            aiAttackDefense.recordAuthFailure()            PinVerificationResult.WrongPin        }    }    /**     * Set or change the PIN. The PIN is hashed with Argon2 before storage;     * the raw PIN is never persisted.     *     * @param pin the new PIN (4-6 ASCII digits).     * @return true if the PIN was stored successfully.     * @throws IllegalArgumentException if [pin] is not 4-6 ASCII digits.     */    suspend fun setPin(pin: CharArray): Boolean {        // CRITICAL FIX #78: Validate and securely handle PIN        val pinCopy = pin.copyOf()        try {            return performSetPin(pinCopy)        } finally {            pinCopy.fill('0')        }    }        /**     * Internal setPIN without memory cleanup (caller handles that).     */    private suspend fun performSetPin(pin: CharArray): Boolean {        // Validate at the entry point too (defence-in-depth — SqlCipherPinStorage        // also validates). This guards against alternative PinStorage impls        // that may forget to validate.        require(pin.size in PIN_MIN_DIGITS..PIN_MAX_DIGITS) {            "PIN must be $PIN_MIN_DIGITS-$PIN_MAX_DIGITS digits, got ${pin.size}"        }        require(pin.all { it.isDigit() }) {            "PIN must contain only ASCII digits (0-9)"        }        val ok = pinStorage.setPin(pin)        if (ok) aiAttackDefense.resetAuthAttempts()        return ok    }    /** True if a PIN has been set. */    fun isPinSet(): Boolean = pinStorage.isPinSet()    /** Clear the stored PIN (used for "disable app lock" flow). */    suspend fun clearPin() {        pinStorage.clearPin()        aiAttackDefense.resetAuthAttempts()    }    // ─── Passkey (Credential Manager API) ────────────────────────────────────    /**     * Create a new passkey for the user.     *     * Uses the Credential Manager API (FIDO2/WebAuthn). The passkey is     * stored in the user's Google Password Manager (synced across the     * user's Android devices signed in to the same Google account).     *     * On success, sets the [KEY_PASSKEY_REGISTERED] flag in     * [EncryptedStorage] so [hasRegisteredPasskey] returns `true` for     * [getRecommendedAuthMethod].     *     * @param host the host [FragmentActivity].     * @param userId the user's account ID (typically their email).     * @param challenge server-issued challenge bytes (base64). In a real     *   deployment this comes from NOUS's backend; here we accept any     *   caller-provided challenge.     * @return the JSON-encoded passkey registration response, or null on failure.     */    suspend fun createPasskey(        host: FragmentActivity,        userId: String,        challenge: String,    ): String? {        val requestJson = buildCreatePasskeyRequestJson(userId, challenge)        val request = CreatePublicKeyCredentialRequest(requestJson)        return try {            val result = credentialManager.createCredential(host, request)            val json = (result as? CreatePublicKeyCredentialResponse)?.registrationResponseJson            if (json != null) {                encryptedStorage.putString(KEY_PASSKEY_REGISTERED, "true")                Timber.tag("NOUS.Security").i("Passkey registered for user=%s", userId)            }            json        } catch (e: CreateCredentialException) {            Timber.tag("NOUS.Security").w(e, "Passkey creation failed: %s", e.type)            null        }    }    /**     * Authenticate the user with an existing passkey.     *     * @param host the host [FragmentActivity].     * @param challenge server-issued challenge bytes (base64).     * @return the JSON-encoded assertion response (for server verification),     *   or null on failure.     */    suspend fun authenticateWithPasskey(        host: FragmentActivity,        challenge: String,    ): String? {        // Pre-check: brute-force lockout.        val decision = aiAttackDefense.recordAuthAttempt()        if (decision is AttemptResult.Blocked) {            Timber.tag("NOUS.Security").w("Passkey auth blocked by brute-force defense")            return null        }        val requestJson = buildGetPasskeyRequestJson(challenge)        val option = GetPublicKeyCredentialOption(requestJson)        return try {            val result = credentialManager.getCredential(host, androidx.credentials.GetCredentialRequest(listOf(option)))            (result.credential as? PublicKeyCredential)?.authenticationResponseJson        } catch (e: GetCredentialException) {            Timber.tag("NOUS.Security").w(e, "Passkey auth failed: %s", e.type)            null        }    }    // ─── Recommendations ─────────────────────────────────────────────────────    /**     * Whether the user has registered a passkey with NOUS.     *     * The Credential Manager API does NOT expose a synchronous "list     * registered passkeys" call (any `getCredential` flow requires user     * interaction). So we track passkey registration via a boolean flag in     * [EncryptedStorage] — set by [createPasskey] on success, cleared by     * [clearPasskey] on user request.     *     * @return true if [createPasskey] has previously succeeded on this device.     */    fun hasRegisteredPasskey(): Boolean {        return encryptedStorage.getString(KEY_PASSKEY_REGISTERED, null) == "true"    }    /**     * Clear the passkey registration flag (used when the user revokes a     * passkey from Google Password Manager and wants NOUS to stop     * recommending PASSKEY as the auth method).     */    fun clearPasskey() {        encryptedStorage.remove(KEY_PASSKEY_REGISTERED)    }    /**     * Get the recommended auth method (most secure available).     *     * Priority: BIOMETRIC > PASSKEY > PIN > NONE.     *     *   1. **BIOMETRIC** — if `BiometricManager.canAuthenticate(BIOMETRIC_STRONG)`     *      returns `BIOMETRIC_SUCCESS` (Class 3 biometric enrolled).     *   2. **PASSKEY** — if a passkey has been registered via [createPasskey]     *      (queried via [hasRegisteredPasskey]).     *   3. **PIN** — if [isPinSet] returns true.     *   4. **NONE** — no auth method configured.     */    fun getRecommendedAuthMethod(): RecommendedAuthMethod {        if (checkBiometricAvailability() == BiometricAvailability.AVAILABLE_ENROLLED) {            return RecommendedAuthMethod.BIOMETRIC        }        if (hasRegisteredPasskey()) return RecommendedAuthMethod.PASSKEY        if (isPinSet()) return RecommendedAuthMethod.PIN        return RecommendedAuthMethod.NONE    }    // ─── Helpers ─────────────────────────────────────────────────────────────    /**     * Build the WebAuthn JSON for `createCredential`.     *     * CRITICAL FIX #7: Properly sanitize and escape JSON inputs to prevent injection.     * Using JSONObject for safe JSON construction instead of string concatenation.     */    private fun buildCreatePasskeyRequestJson(userId: String, challenge: String): String {        return try {            val json = org.json.JSONObject().apply {                put("rp", org.json.JSONObject().apply { put("name", "NOUS") })                put("user", org.json.JSONObject().apply {                    // CRITICAL FIX #8: Sanitize userId to prevent JSON injection                    put("id", sanitizeJsonString(userId))                    put("name", sanitizeJsonString(userId))                    put("displayName", sanitizeJsonString(userId))                })                put("challenge", sanitizeJsonString(challenge))                put("pubKeyCredParams", org.json.JSONArray().apply {                    put(org.json.JSONObject().apply {                        put("type", "public-key")                        put("alg", -7)                    })                    put(org.json.JSONObject().apply {                        put("type", "public-key")                        put("alg", -257)                    })                })                put("authenticatorSelection", org.json.JSONObject().apply {                    put("authenticatorAttachment", "platform")                    put("userVerification", "required")                })            }            json.toString(2)        } catch (e: Exception) {            Timber.tag("NOUS.Security").w(e, "Failed to build passkey request JSON")                "{}"        }    }    private fun buildGetPasskeyRequestJson(challenge: String): String {        return try {            val json = org.json.JSONObject().apply {                // CRITICAL FIX #9: Sanitize challenge to prevent JSON injection                put("challenge", sanitizeJsonString(challenge))                put("userVerification", "required")                put("allowCredentials", org.json.JSONArray())            }            json.toString(2)        } catch (e: Exception) {            Timber.tag("NOUS.Security").w(e, "Failed to build get passkey request JSON")            "{}"        }    }    private companion object {        const val KEY_PASSKEY_REGISTERED = "passkey_registered"        const val PIN_MIN_DIGITS = 4        const val PIN_MAX_DIGITS = 6    }        /**     * CRITICAL FIX #12: Sanitize string for safe JSON inclusion.     * Escapes special characters to prevent JSON injection attacks.     */    private fun sanitizeJsonString(input: String): String {        return input            .replace("\\", "\\\\")  // Escape backslashes first            .replace("\"", "\\\"")  // Escape double quotes            .replace("\n", "\\n")   // Escape newlines            .replace("\r", "\\r")   // Escape carriage returns            .replace("\t", "\\t")   // Escape tabs            // Control characters U+0000 through U+001F (except already handled)            .replace(Regex("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]")) { match ->                String.format("\\u%04x", match.value[0].code)            }    }}